import{_ as a,o as e,c as d,ag as o}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"礼","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-礼.md","filePath":"50-概念资料/dict-礼.md","lastUpdated":null}'),r={name:"50-概念资料/dict-礼.md"};function l(i,t,h,n,c,u){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="礼" tabindex="-1">礼 <a class="header-anchor" href="#礼" aria-label="Permalink to &quot;礼&quot;">​</a></h1><blockquote><p>传统：儒家 | 佛家对应：威仪 | 道家对应：仪式（和光同尘则不执）</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;礼&quot;就是<strong>合适的形式</strong>。了空居士谈&quot;礼&quot;非常辩证：形式和仪式有它们的意义，但不要被形式绑住。礼是工具不是目的——释迦牟尼佛对须菩提提问，没有说&quot;等一下我去穿袈裟&quot;，直接就说。这就是不执形式，但不否定形式的用处。</p><p>他用《弟子规》概括&quot;礼&quot;的实质：听话、有礼貌、好好学习——三句话就完了。礼的核心不是繁复的规则，而是<strong>对人的恭敬</strong>。有恭敬心，形式自然得体；没恭敬心，形式再对也只是空壳。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;不要说须菩提一提问，佛赶快跑过去穿上袈裟来讲…就没有这种执着。&quot; — <a href="/60-原文段落/金刚经1分-不执形式">金刚经1分-不执形式</a></p></blockquote><blockquote><p>&quot;《弟子规》一百多条，我概括成三方面：听话、有礼貌、好好学习。&quot; — <a href="/60-原文段落/金刚经1分-化繁为简弟子规">金刚经1分-化繁为简弟子规</a></p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>礼就是繁文缛节</td><td>礼的核心是恭敬心，形式在其次</td></tr><tr><td>修行人不该讲究形式</td><td>合适的形式有助于修行——双盘利于中正安舒，但不是必须</td></tr></tbody></table><h2 id="跨传统对比" tabindex="-1">跨传统对比 <a class="header-anchor" href="#跨传统对比" aria-label="Permalink to &quot;跨传统对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>对应概念</th><th>侧重</th></tr></thead><tbody><tr><td>儒家</td><td>礼</td><td>规范社会关系的仪式和准则</td></tr><tr><td>佛家</td><td>威仪</td><td>修行人的行住坐卧规范</td></tr><tr><td>道家</td><td>不执仪式</td><td>和光同尘，不拘形式</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-敬">dict-敬</a> — 礼的内在核心是敬，有敬礼才有内容</li><li><a href="/50-概念资料/dict-处世">dict-处世</a> — 礼是处世的仪表和仪态</li><li><a href="/50-概念资料/dict-不执形式">对法不执</a> — 不执著于礼的形式</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对法不执">model-对法不执</a> — 不执著于形式，但也不否定形式的用处</li><li><a href="/10-核心模型/model-历境炼心">model-历境炼心</a> — 在细节（如穿衣、吃饭）中体现礼</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>待人接物时注意仪表和态度——不是拘泥形式，是让对方感到被尊重。在家对家人有礼貌，在公司对同事有礼貌。恭敬心是里，礼貌是表。</p>',18)])])}const b=a(r,[["render",l]]);export{q as __pageData,b as default};
